<?php
declare(strict_types=1);
if(session_status()!==PHP_SESSION_ACTIVE)session_start();
require_once __DIR__.'/../lib/platform.php';
if(empty($_SESSION['ferrn_admin'])){header('Location:/admin/');exit;}
if(realpath($_SERVER['SCRIPT_FILENAME']??'')===__FILE__ && $_SERVER['REQUEST_METHOD']==='GET'){header('Location:/admin/?tab='.urlencode((string)($_GET['tab']??'overview')));exit;}
if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));
function v2_csrf():string{return (string)$_SESSION['csrf'];}
function v2_valid():void{if(!hash_equals((string)($_SESSION['csrf']??''),(string)($_POST['csrf']??''))){http_response_code(403);exit('Invalid request');}}
function v2_go(string $tab):never{header('Location:/admin/?tab='.urlencode($tab));exit;}
$tabs=['overview','settings','team','certifications','awards','policies','careers','rfps','newsletter','analytics','knowledge'];
$tab=in_array((string)($_GET['tab']??'overview'),$tabs,true)?(string)($_GET['tab']??'overview'):'overview';
$noticeError='';
if($_SERVER['REQUEST_METHOD']==='POST'){v2_valid();$action=(string)($_POST['action']??'');
 if($action==='import_knowledge'){
    $title=trim((string)($_POST['title']??''));
    try{
        if($title==='')throw new RuntimeException('Provide a source title.');
        require_once __DIR__.'/../lib/knowledge-import.php';
        $kind=(string)($_POST['source_type']??'');
        if($kind==='pdf')$source=ferrn_import_knowledge_pdf($_FILES['pdf_document']??[]);
        elseif($kind==='website')$source=ferrn_import_knowledge_url(trim((string)($_POST['website_url']??'')));
        else throw new RuntimeException('Choose a source.');
        $item=array_merge(['id'=>ferrn_item_id(),'title'=>ferrn_safe_text($title,220),'published'=>false,'updated_at'=>date(DATE_ATOM)],$source);
        $items=ferrn_collection('knowledge');$items[]=$item;
        if(!ferrn_save_collection('knowledge',$items))throw new RuntimeException('Could not save knowledge.');
        v2_go('knowledge');
    }catch(Throwable $e){$noticeError=$e->getMessage();}
 }

 if($action==='save_settings'){
   $s=ferrn_settings();
   foreach(['legal_name','tagline'] as $k)$s['brand'][$k]=ferrn_safe_text((string)($_POST[$k]??$s['brand'][$k]),200);
   foreach(['email','phone','booking_url','address','country'] as $k)$s['contact'][$k]=ferrn_safe_text((string)($_POST[$k]??$s['contact'][$k]),500);
   foreach(['registration_jurisdiction','registration_number','year_established','ownership_structure','tax_information','geographic_coverage','procurement_contact','capability_statement_url','company_profile_url'] as $k)$s['company'][$k]=ferrn_safe_text((string)($_POST[$k]??$s['company'][$k]),1000);
   $s['ai']['enabled']=!empty($_POST['ai_enabled']);$s['ai']['auto_publish']=!empty($_POST['auto_publish']);$s['ai']['articles_per_day']=max(1,min(10,(int)($_POST['articles_per_day']??10)));$s['ai']['trend_region']=strtoupper(substr((string)($_POST['trend_region']??'NG'),0,2));$s['ai']['text_model']=ferrn_safe_text((string)($_POST['text_model']??$s['ai']['text_model']),100);$s['ai']['image_model']=ferrn_safe_text((string)($_POST['image_model']??$s['ai']['image_model']),100);
   $s['chatbot']['enabled']=!empty($_POST['chatbot_enabled']);$s['chatbot']['name']=ferrn_safe_text((string)($_POST['chatbot_name']??'Ferrn Assistant'),100);$s['chatbot']['welcome']=ferrn_safe_text((string)($_POST['chatbot_welcome']??''),600);
   ferrn_save_settings($s);v2_go('settings');
 }
 if($action==='save_collection_item'){
   $collection=(string)($_POST['collection']??'');if(!in_array($collection,['team','certifications','awards','policies','careers','knowledge'],true))exit('Invalid collection');
   $items=($collection==='policies'?ferrn_policies():ferrn_collection($collection));
   $id=ferrn_safe_text((string)($_POST['id']??''),120);if($id==='')$id=ferrn_item_id();
   $item=['id'=>$id,'updated_at'=>date(DATE_ATOM)];
   if($collection==='team')$item+=['name'=>ferrn_safe_text((string)($_POST['name']??''),160),'role'=>ferrn_safe_text((string)($_POST['role']??''),160),'bio'=>ferrn_safe_text((string)($_POST['bio']??''),1800),'headshot'=>ferrn_safe_text((string)($_POST['headshot']??''),800),'linkedin'=>ferrn_safe_text((string)($_POST['linkedin']??''),800),'published'=>!empty($_POST['published'])];
   if($collection==='certifications')$item+=['name'=>ferrn_safe_text((string)($_POST['name']??''),200),'issuer'=>ferrn_safe_text((string)($_POST['issuer']??''),200),'credential_url'=>ferrn_safe_text((string)($_POST['credential_url']??''),800),'date'=>ferrn_safe_text((string)($_POST['date']??''),60),'published'=>!empty($_POST['published'])];
   if($collection==='awards')$item+=['name'=>ferrn_safe_text((string)($_POST['name']??''),200),'issuer'=>ferrn_safe_text((string)($_POST['issuer']??''),200),'url'=>ferrn_safe_text((string)($_POST['url']??''),800),'year'=>ferrn_safe_text((string)($_POST['year']??''),20),'published'=>!empty($_POST['published'])];
   if($collection==='policies')$item+=['title'=>ferrn_safe_text((string)($_POST['title']??''),220),'slug'=>ferrn_slugify((string)($_POST['slug']??$_POST['title']??'')),'summary'=>ferrn_safe_text((string)($_POST['summary']??''),800),'content'=>ferrn_sanitize_html((string)($_POST['content']??'')),'published'=>!empty($_POST['published'])];
   if($collection==='careers')$item+=['title'=>ferrn_safe_text((string)($_POST['title']??''),160),'location'=>ferrn_safe_text((string)($_POST['location']??''),120),'employment'=>ferrn_safe_text((string)($_POST['employment']??''),120),'description'=>ferrn_safe_text((string)($_POST['description']??''),6000),'apply_url'=>ferrn_safe_text((string)($_POST['apply_url']??''),800),'published'=>!empty($_POST['published'])];
   if($collection==='knowledge')$item+=['title'=>ferrn_safe_text((string)($_POST['title']??''),220),'content'=>mb_substr(trim((string)($_POST['content']??'')),0,35000),'published'=>!empty($_POST['published'])];
   $found=false;foreach($items as &$x){if(($x['id']??'')===$id){$x=array_merge($x,$item);$found=true;break;}}unset($x);if(!$found)$items[]=$item;ferrn_save_collection($collection,$items);v2_go($collection);
 }
 if($action==='delete_collection_item'){
   $collection=(string)($_POST['collection']??'');$id=(string)($_POST['id']??'');if(!in_array($collection,['team','certifications','awards','policies','careers','knowledge'],true))exit('Invalid collection');
   $source=$collection==='policies'?ferrn_policies():ferrn_collection($collection);
   if($collection==='knowledge')foreach($source as $x)if(($x['id']??'')===$id&&!empty($x['stored_file'])){@unlink(ferrn_storage_dir().'/knowledge-documents/'.basename((string)$x['stored_file']));}
   $items=array_values(array_filter($source,fn($x)=>($x['id']??'')!==$id));ferrn_save_collection($collection,$items);v2_go($collection);
 }
 if($action==='rfp_status'){$items=ferrn_collection('rfps');$id=(string)($_POST['id']??'');$status=(string)($_POST['status']??'new');if(!in_array($status,['new','reviewing','qualified','proposal','won','lost','archived'],true))$status='new';foreach($items as &$x)if(($x['id']??'')===$id)$x['status']=$status;unset($x);ferrn_save_collection('rfps',$items);v2_go('rfps');}
}
if(isset($_GET['export'])&&$_GET['export']==='newsletter'){header('Content-Type:text/csv; charset=utf-8');header('Content-Disposition:attachment; filename="ferrn-newsletter-'.date('Y-m-d').'.csv"');$o=fopen('php://output','w');fputcsv($o,['Email','Name','Status','Source','Subscribed At']);foreach(ferrn_collection('newsletter') as $x)fputcsv($o,[$x['email']??'',$x['name']??'',$x['status']??'',$x['source']??'',$x['created_at']??'']);fclose($o);exit;}
$settings=ferrn_settings();$collections=[];foreach(['team','certifications','awards','policies','careers','knowledge','rfps','newsletter','analytics'] as $c)$collections[$c]=($c==='policies'?ferrn_policies():ferrn_collection($c));
